table.sort(__OMEN_ZH_TRANSLATIONS, function(a, b) return #a[1] > #b[1] end)

local function __omenReplacePlain(value, source, target)
    local out, start = {}, 1
    while true do
        local first, last = string.find(value, source, start, true)
        if not first then
            table.insert(out, string.sub(value, start))
            return table.concat(out)
        end
        table.insert(out, string.sub(value, start, first - 1))
        table.insert(out, target)
        start = last + 1
    end
end

local function __omenTranslate(value)
    if type(value) ~= "string" or value == "" then return value end
    local translated = value
    for _, pair in ipairs(__OMEN_ZH_TRANSLATIONS) do
        translated = __omenReplacePlain(translated, pair[1], pair[2])
    end
    return translated
end

local __omenOriginalText = setmetatable({}, {__mode = "k"})
local __omenApplying = false
local function __omenTranslateElement(element)
    if __omenApplying or not (element:IsA("TextLabel") or element:IsA("TextButton") or element:IsA("TextBox")) then return end
    local current = element.Text
    if type(current) ~= "string" or current == "" then return end
    local lastApplied = element:GetAttribute("OMEN_ZH_LastApplied")
    if current ~= lastApplied then __omenOriginalText[element] = current end
    local translated = __omenTranslate(__omenOriginalText[element] or current)
    if translated ~= current then
        __omenApplying = true
        element:SetAttribute("OMEN_ZH_LastApplied", translated)
        element.Text = translated
        __omenApplying = false
    end
end

local function __omenHookElement(element)
    if not (element:IsA("TextLabel") or element:IsA("TextButton") or element:IsA("TextBox")) then return end
    __omenTranslateElement(element)
    if not element:GetAttribute("OMEN_ZH_Hooked") then
        element:SetAttribute("OMEN_ZH_Hooked", true)
        element:GetPropertyChangedSignal("Text"):Connect(function()
            __omenTranslateElement(element)
        end)
    end
end

task.spawn(function()
    local roots = {game:GetService("CoreGui")}
    if gethui then
        local ok, hui = pcall(gethui)
        if ok and hui and hui ~= roots[1] then table.insert(roots, hui) end
    end
    local player = game:GetService("Players").LocalPlayer
    if player and player:FindFirstChild("PlayerGui") then table.insert(roots, player.PlayerGui) end
    for _, root in ipairs(roots) do
        for _, element in ipairs(root:GetDescendants()) do __omenHookElement(element) end
        root.DescendantAdded:Connect(__omenHookElement)
    end
    while task.wait(0.5) do
        for _, root in ipairs(roots) do
            for _, element in ipairs(root:GetDescendants()) do __omenHookElement(element) end
        end
    end
end)

return __OMEN_RESULT
